from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = m
            prev = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if i == n - 1:
                    deficit = need - prev
                    if deficit > 0:
                        moves -= 2 * deficit - 1
                else:
                    if need <= prev:
                        moves -= 1
                        prev = 0
                    else:
                        add = need - prev
                        moves -= 2 * add - 1
                        prev = add - 1

                if moves < 0:
                    return False

            return True

        lo, hi = 0, min(points) * ((m + 1) // 2 + 1)

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
